    print('字段写错:', e)

def classify(fn):
    try:
        fn()
        return 'ok'
    except IndexError:
        return 'IndexError'
    except KeyError:
        return 'KeyError'
    except Exception as e:
        return type(e).__name__

print(classify(lambda: [][0]))
print(classify(lambda: {}['x']))
